package com.hbm.machine.radar;
import api.hbm.entity.*;import com.hbm.api.computer.*;import com.hbm.bomb.nuclear.SatelliteBursts;import com.hbm.energy.*;import com.hbm.exposure.HbmExposure;import com.hbm.item.battery.*;import com.hbm.item.coordinate.CoordinateItem;import com.hbm.machine.foundry.crucible.ThermalMachine;import com.hbm.multiblock.DummyableBlock;import com.hbm.radar.*;import com.hbm.registry.HbmSounds;import com.hbm.satellite.SatelliteRayEvents;import java.util.*;import java.util.function.*;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.server.level.*;import net.minecraft.sounds.SoundSource;import net.minecraft.util.Mth;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.levelgen.Heightmap;
/** Source SmЯt global-cache radar, full scan/control/map/persistence and10actualOC→CC callbacks. */
public final class RadarBlockEntity extends ThermalMachine implements EnergyReceiver,SidedEnergyConnector,ComputerControl{
 public final boolean large;public boolean scanMissiles=true,scanShells=true,scanPlayers=true,smartMode=true,redMode=true,showMap,jammed,clearFlag;public float prevRotation,rotation;public long power;public int clientRange,clientMaxPower,clientConsumption;public boolean tilted;private int pingTimer,lastPower;public byte[] map=new byte[40000];public final List<RadarEntry> entries=new ArrayList<>();private final Map<BlockPos,PowerNode> nodes=new LinkedHashMap<>();private final RadarChunkAccess chunks=new RadarChunkAccess();public static Consumer<BlockPos> OPEN=pos->{};public record Scan(Entity entity,Object radar,IRadarDetectableNT.RadarScanParams params){}public static final List<Function<Scan,RadarEntry>> CONVERTERS=new ArrayList<>();
 static{CONVERTERS.add(scan->{if(scan.entity instanceof IRadarDetectableNT d&&d.canBeSeenBy(scan.radar)&&d.paramsApplicable(scan.params))return new RadarEntry(d,scan.entity,d.suppliesRedstone(scan.params));return null;});CONVERTERS.add(scan->scan.entity instanceof IRadarDetectable d&&scan.params.scanMissiles?new RadarEntry(d,scan.entity):null);CONVERTERS.add(scan->scan.entity instanceof Player p&&scan.params.scanPlayers?new RadarEntry(p):null);}
 public RadarBlockEntity(BlockPos pos,BlockState state){this(pos,state,false);}public RadarBlockEntity(BlockPos pos,BlockState state,boolean large){super(large?RadarContent.LARGE_ENTITY.get():RadarContent.ENTITY.get(),pos,state,10);this.large=large;}@Override public boolean isValidBlockState(BlockState state){return getType().isValid(state)&&(!state.hasProperty(DummyableBlock.LEGACY_META)||DummyableBlock.isCore(state));}@Override protected String title(){return "container.radar";}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new RadarMenu(id,inventory,this,worldPosition);}public int range(){return level!=null&&level.isClientSide&&clientRange>0?clientRange:large?RadarConfig.largeRange:RadarConfig.range;}
 public static List<BlockPos> ports(BlockPos p,boolean large){return large?List.of(p.north(),p.east(),p.south(),p.west()):List.of(p);}private Direction[] sides(BlockPos p){if(!large)return Direction.values();return new Direction[]{p.getX()>worldPosition.getX()?Direction.EAST:p.getX()<worldPosition.getX()?Direction.WEST:p.getZ()>worldPosition.getZ()?Direction.SOUTH:Direction.NORTH};}
 private void updatePorts(ServerLevel level){var positions=ports(worldPosition,large).stream().filter(p->!large||level.hasChunkAt(p)&&level.getBlockState(p).is(getBlockState().getBlock())&&DummyableBlock.isPort(level.getBlockState(p))).toList();if(!nodes.keySet().equals(new LinkedHashSet<>(positions))||nodes.values().stream().anyMatch(PowerNode::isExpired)){disconnect();for(var p:positions){var node=new PowerNode(p).setConnections(Arrays.stream(sides(p)).map(side->new NodeConnection(p.relative(side),side)).toArray(NodeConnection[]::new));HbmEnergy.nodespace(level).createNode(node);nodes.put(p,node);}}for(var node:nodes.values())if(node.hasValidNet())node.addReceiver(this);}
 private void disconnect(){if(level instanceof ServerLevel s)for(var node:nodes.values())if(!node.isExpired())HbmEnergy.nodespace(s).destroyNode(node);nodes.clear();}@Override public void setRemoved(){disconnect();chunks.clear();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();chunks.clear();super.onChunkUnloaded();}
 public static void tick(Level level,BlockPos pos,BlockState state,RadarBlockEntity radar){if(radar.map==null||radar.map.length!=40000)radar.map=new byte[40000];if(level instanceof ServerLevel server)radar.serverTick(server);else{radar.prevRotation=radar.rotation;if(radar.power>0)radar.rotation+=5;if(radar.rotation>=360){radar.rotation-=360;radar.prevRotation-=360;}}}
 private void chargeBattery(int slot){if(power<0){power=0;return;}if(power>RadarConfig.maxPower){power=RadarConfig.maxPower;return;}var stack=slots.get(slot);if(stack.getItem() instanceof CreativeBatteryItem){power=RadarConfig.maxPower;return;}if(stack.getItem() instanceof HbmBattery battery){long take=Math.min(Math.min(RadarConfig.maxPower-power,battery.getDischargeRate(stack)),battery.getCharge(stack));battery.dischargeBattery(stack,take);power+=take;}}
 private void serverTick(ServerLevel server){updatePorts(server);chargeBattery(9);chargeBattery(0);jammed=false;allocateTargets(server);int signal=redPower();if(lastPower!=signal){setChanged();for(var p:ports(worldPosition,large))for(var side:sides(p))server.updateNeighborsAt(p.relative(side),getBlockState().getBlock());}lastPower=signal;if(!isMuffled()&&++pingTimer>=80&&power>0){server.playSound(null,worldPosition.getX(),worldPosition.getY(),worldPosition.getZ(),HbmSounds.get("block.sonarPing"),SoundSource.BLOCKS,5,1);pingTimer=0;}if(showMap)updateMap(server);
  var display=slots.get(8);if(display.getItem() instanceof RadarLinkerItem){var p=CoordinateItem.position(display);if(p!=null&&server.getBlockEntity(p) instanceof RadarScreenBlockEntity screen){screen.entries.clear();screen.entries.addAll(entries);screen.refX=worldPosition.getX();screen.refY=worldPosition.getY();screen.refZ=worldPosition.getZ();screen.range=range();screen.linked=true;screen.sync(25);}}
  var nearest=nearestEntry();if(nearest!=null)for(int i=0;i<8;i++)if(slots.get(i).getItem() instanceof RadarLinkerItem){var p=CoordinateItem.position(slots.get(i));if(p!=null&&server.getBlockEntity(p) instanceof RadarTurretReceiver turret){var entity=server.getEntity(nearest.entityID);if(entity!=null&&entity.isAlive())turret.sendCommandEntity(entity);}}
  RadarStatePacket.send(server,this,50);if(clearFlag){map=new byte[40000];clearFlag=false;}setChanged();
 }
 private void updateMap(ServerLevel server){int loads=0;for(int i=0;i<100;i++){int index=(int)(server.getGameTime()%400)*100+i;int x=worldPosition.getX()-range()+(index%200)*range()*2/200,z=worldPosition.getZ()-range()+index/200*range()*2/200;var chunk=server.getChunkSource().getChunkNow(x>>4,z>>4);if(chunk!=null)map[index]=(byte)Mth.clamp(chunk.getHeight(Heightmap.Types.WORLD_SURFACE,x&15,z&15)+1,50,128);else if(map[index]==0&&loads<RadarConfig.chunkLoadCap){if(RadarConfig.generateChunks){server.getChunk(x>>4,z>>4);map[index]=(byte)Mth.clamp(server.getHeight(Heightmap.Types.WORLD_SURFACE,x,z),50,128);loads++;}else{if(chunks.provide(server,x>>4,z>>4)){map[index]=(byte)Mth.clamp(server.getHeight(Heightmap.Types.WORLD_SURFACE,x,z),50,128);loads++;}}}}}
 private void allocateTargets(ServerLevel server){entries.clear();if(worldPosition.getY()<RadarConfig.altitude)return;if(power<RadarConfig.consumption){power=0;return;}power-=RadarConfig.consumption;var params=new IRadarDetectableNT.RadarScanParams(scanMissiles,scanShells,scanPlayers,smartMode);for(var entity:RadarTargetCache.matchingEntities()){if(entity.level()!=level||Math.abs(entity.getX()-(worldPosition.getX()+.5))>range()||Math.abs(entity.getZ()-(worldPosition.getZ()+.5))>range()||entity.getY()-worldPosition.getY()<=RadarConfig.buffer)continue;if(entity instanceof LivingEntity living&&HbmExposure.digamma(living)>.001){jammed=true;entries.clear();return;}for(var converter:CONVERTERS){var entry=converter.apply(new Scan(entity,this,params));if(entry!=null){entries.add(entry);break;}}}if(server.getGameTime()%20==0){SatelliteBursts.reportEvent(server,SatelliteBursts.DURATION_MEDIUM,SatelliteBursts.BurstIntensity.MEDIUM,worldPosition.getX(),worldPosition.getZ());SatelliteRayEvents.reportEvent(server,worldPosition.getX(),worldPosition.getY(),worldPosition.getZ(),SatelliteRayEvents.RayEvent.INFO_RADAR,200);}}
 public RadarEntry nearestEntry(){RadarEntry nearest=null;double distance=range()*range();for(var entry:entries){double dx=entry.posX-worldPosition.getX(),dy=entry.posY-worldPosition.getY(),dz=entry.posZ-worldPosition.getZ(),d=Math.sqrt(dx*dx+dy*dy+dz*dz);if(d<=distance){var entity=level.getEntity(entry.entityID);if(entity==null||!entity.isAlive())continue;distance=d;nearest=entry;}}return nearest;}
 public int redPower(){int out=0;for(var entry:entries){if(!entry.redstone)continue;int p;if(redMode){double dx=entry.posX-worldPosition.getX(),dz=entry.posZ-worldPosition.getZ();p=15-(int)Math.floor(Math.sqrt(dx*dx+dz*dz)/(range()*Math.sqrt(2))*15);}else p=entry.blipLevel+1;if(p>out)out=p;}return out;}
 public void control(Player player,CompoundTag data){if(!stillValid(player))return;if(data.contains("missiles"))scanMissiles=!scanMissiles;if(data.contains("shells"))scanShells=!scanShells;if(data.contains("players"))scanPlayers=!scanPlayers;if(data.contains("smart"))smartMode=!smartMode;if(data.contains("red"))redMode=!redMode;if(data.contains("map"))showMap=!showMap;if(data.contains("clear"))clearFlag=true;if(data.contains("gui1")&&player instanceof ServerPlayer server)server.openMenu(this,worldPosition);if(data.contains("link")){int index=data.getInt("link");if(index<0||index>=8)return;var stack=slots.get(index);var backend=RadarSatelliteBridge.backend;if(backend!=null&&backend.isRelay(stack)&&data.contains("launchPosX")){level.playSound(null,player.getX(),player.getY(),player.getZ(),HbmSounds.get("item.techBleep"),SoundSource.PLAYERS,1,1);backend.onCoordinate(level,player,stack,data.getInt("launchPosX"),60,data.getInt("launchPosZ"));}if(stack.getItem() instanceof RadarLinkerItem){var p=CoordinateItem.position(stack);if(p!=null&&level.getBlockEntity(p) instanceof IRadarCommandReceiver receiver&&!(receiver instanceof RadarTurretReceiver)){boolean success=false;if(data.contains("launchEntity")){var entity=level.getEntity(data.getInt("launchEntity"));if(entity!=null)success=receiver.sendCommandEntity(entity);}else if(data.contains("launchPosX"))success=receiver.sendCommandPosition(data.getInt("launchPosX"),worldPosition.getY(),data.getInt("launchPosZ"));if(success)level.playSound(null,player.getX(),player.getY(),player.getZ(),HbmSounds.get("item.techBleep"),SoundSource.PLAYERS,1,1);}}}setChanged();}
 @Override public boolean stillValid(Player player){return level!=null&&level.getBlockEntity(worldPosition)==this;}@Override public int[] getSlotsForFace(Direction side){return new int[0];}@Override public boolean canPlaceItem(int slot,ItemStack stack){return false;}@Override public long getPower(){return power;}@Override public long getMaxPower(){return level!=null&&level.isClientSide&&clientMaxPower>0?clientMaxPower:RadarConfig.maxPower;}@Override public void setPower(long value){power=value;setChanged();}@Override public boolean isLoaded(){return !isRemoved()&&level!=null;}@Override public boolean canConnect(Direction side){return side!=null;}@Override public long energyStored(){return power;}@Override public long energyCapacity(){return RadarConfig.maxPower;}
 @Override protected void saveMachine(CompoundTag tag){tag.putLong("power",power);tag.putBoolean("tilted",tilted);tag.putBoolean("scanMissiles",scanMissiles);tag.putBoolean("scanShells",scanShells);tag.putBoolean("scanPlayers",scanPlayers);tag.putBoolean("smartMode",smartMode);tag.putBoolean("redMode",redMode);tag.putBoolean("showMap",showMap);tag.putByteArray("map",map);}@Override protected void loadMachine(CompoundTag tag){power=tag.getLong("power");tilted=tag.getBoolean("tilted");scanMissiles=tag.getBoolean("scanMissiles");scanShells=tag.getBoolean("scanShells");scanPlayers=tag.getBoolean("scanPlayers");smartMode=tag.getBoolean("smartMode");redMode=tag.getBoolean("redMode");showMap=tag.getBoolean("showMap");if(tag.contains("map"))map=tag.getByteArray("map");}
 @Override public String computerType(){return "ntm_radar";}@Override public String[] computerMethods(){return new String[]{"getSettings","getRange","setSettings","getEnergyInfo","isJammed","getAmount","isIndexPlayer","getIndexType","getEntityAtIndex","getPos"};}@Override public Object[] callComputer(String method,ComputerArguments args){return switch(method){case "getSettings"->new Object[]{scanMissiles,scanShells,scanPlayers,smartMode};case "getRange"->new Object[]{range()};case "setSettings"->{scanMissiles=args.checkBoolean(0);scanShells=args.checkBoolean(1);scanPlayers=args.checkBoolean(2);smartMode=args.checkBoolean(3);setChanged();yield new Object[]{};}case "getEnergyInfo"->new Object[]{power,RadarConfig.maxPower};case "isJammed"->new Object[]{jammed};case "getAmount"->new Object[]{entries.size()};case "isIndexPlayer","getIndexType","getEntityAtIndex"->{int i=args.checkInteger(0)-1;if(i<0||i>=entries.size())yield new Object[]{null,"No entity exists at that index."};var entry=entries.get(i);yield method.equals("isIndexPlayer")?new Object[]{entry.blipLevel==IRadarDetectableNT.PLAYER}:method.equals("getIndexType")?new Object[]{entry.blipLevel}:entry.blipLevel==IRadarDetectableNT.PLAYER?new Object[]{true,entry.posX,entry.posY,entry.posZ,entry.blipLevel,entry.unlocalizedName,entry.entityID}:new Object[]{false,entry.posX,entry.posY,entry.posZ,entry.blipLevel,entry.entityID};}case "getPos"->new Object[]{worldPosition.getX(),worldPosition.getY(),worldPosition.getZ()};default->throw new ComputerException("No such method");};}
}
